import javax.swing.*;
import java.awt.*;
import java.awt.geom.Ellipse2D;
import java.util.ArrayList;
import java.util.Random;

public class Main extends JFrame {
    private static JPanel mainPanel;
    public static MazeLabel[][] mazeLabels;       //25*20
    private JButton startBtn;
    private JButton primStart;
    private JButton findWayBtn;
    private JButton refresh;
    private String introductionStr;
    private JLabel introduction;

    public Main() {
        mainPanel = new JPanel();
        mazeLabels = new MazeLabel[20][25];
        startBtn = new JButton("深度优先算法开始");
        primStart = new JButton("随机Prim算法开始");
        refresh = new JButton("刷新");
        findWayBtn = new JButton("寻找一条路");
        initFrame();
        initPanel();
        initTable();
        initComp();
        setVisible(true);
    }

    private void initFrame() {
        setSize(900, 622);
        setLocationRelativeTo(null);
        setTitle("Maze");
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setResizable(false);
    }

    private void initPanel() {
        mainPanel.setLayout(null);
        setContentPane(mainPanel);
    }

    private void initTable() {
        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < 25; j++) {
                mazeLabels[i][j] = new MazeLabel();
                mazeLabels[i][j].setBounds(150 + j * 30, i * 30, 30, 30);
                mazeLabels[i][j].row = i;
                mazeLabels[i][j].col = j;
                mainPanel.add(mazeLabels[i][j]);
            }
        }
