class MazeTools{
    private static int row;
    private static int col;
    private static int top;
    private static Random random;

    public static void generateNewMaze(){
        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < 25; j++) {
                Main.mazeLabels[i][j].initAll();
            }
        }
        top = 0;
        row = 0;
        col = 0;
        random = new Random();
        ArrayList<MazeLabel> list = new ArrayList<>();
        list.add(Main.mazeLabels[0][0]);
        while (top >= 0) {
            int[] dirs = {-1, -1, -1, -1};
            int count = 0;
            boolean moved = false;
            MazeLabel cur = list.get(top);
            row = cur.row;
            col = cur.col;
            cur.setAlready();
            while (count < 4) {
                int d = random.nextInt(4);
                if (dirs[d] == d) {
                    continue;
                }
                dirs[d] = d;
                switch (d) {
                    case 0:
                        if (row >= 1 && !Main.mazeLabels[row - 1][col].getAlready()) {
                            cur.setUpAlready();
                            Main.mazeLabels[row - 1][col].setDownAlready();
                            list.add(Main.mazeLabels[row - 1][col]);
                            top++;
                            moved = true;
                        }
                        break;
                    case 1:
                        if (row <= 18 && !Main.mazeLabels[row + 1][col].getAlready()) {
                            cur.setDownAlready();
                            Main.mazeLabels[row + 1][col].setUpAlready();
                            list.add(Main.mazeLabels[row + 1][col]);
                            top++;
                            moved = true;
                        }
                        break;
                    case 2:
                        if (col >= 1 && !Main.mazeLabels[row][col - 1].getAlready()) {
                            cur.setLeftAlready();
                            Main.mazeLabels[row][col - 1].setRightAlready();
                            list.add(Main.mazeLabels[row][col - 1]);
                            top++;
                            moved = true;
                        }
                        break;
                    case 3:
                        if (col <= 23 && !Main.mazeLabels[row][col + 1].getAlready()) {
                            cur.setRightAlready();
                            Main.mazeLabels[row][col + 1].setLeftAlready();
                            list.add(Main.mazeLabels[row][col + 1]);
                            top++;
                            moved = true;
                        }
                        break;
                    default:
                        break;
                }
                if (moved) {
                    break;
                }
                count++;
            }
            if (!moved) {
                list.remove(top);
                top--;
            }
        }
        Main.mazeLabels[19][24].setTarget();
        Main.mazeLabels[19][24].repaint();
        Main.mazeLabels[0][0].setCurrent();
        Main.mazeLabels[0][0].repaint();
    }
}

class PrimGenerate {
    private static int row;
    private static int col;
    private static Random random;

    public static void primGenerate(){
        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < 25; j++) {
                Main.mazeLabels[i][j].initAll();
            }
        }
        row = 0;
        col = 0;
        random = new Random();
        ArrayList<String> walls = new ArrayList<>();
        Main.mazeLabels[0][0].setAlready();
        walls.add("0,0,1,0");
        walls.add("0,0,0,1");
        while (!walls.isEmpty()) {
            int index = random.nextInt(walls.size());
            String wall = walls.get(index);
            int r1 = Integer.parseInt(wall.split(",")[0]);
            int c1 = Integer.parseInt(wall.split(",")[1]);
            int r2 = Integer.parseInt(wall.split(",")[2]);
            int c2 = Integer.parseInt(wall.split(",")[3]);
            if (Main.mazeLabels[r2][c2].getAlready() ^ Main.mazeLabels[r1][c1].getAlready()) {
                if (r2 < r1) {
                    Main.mazeLabels[r1][c1].setUpAlready();
                    Main.mazeLabels[r2][c2].setDownAlready();
                }
                if (r2 > r1) {
                    Main.mazeLabels[r1][c1].setDownAlready();
                    Main.mazeLabels[r2][c2].setUpAlready();
                }
                if (c2 < c1) {
                    Main.mazeLabels[r1][c1].setLeftAlready();
                    Main.mazeLabels[r2][c2].setRightAlready();
                }
                if (c2 > c1) {
                    Main.mazeLabels[r1][c1].setRightAlready();
                    Main.mazeLabels[r2][c2].setLeftAlready();
                }
                row = r2;
                col = c2;
                Main.mazeLabels[row][col].setAlready();
                if (row >= 1) {
                    walls.add(row + "," + col + "," + (row - 1) + "," + col);
                }
                if (row <= 18) {
                    walls.add(row + "," + col + "," + (row + 1) + "," + col);
                }
                if (col >= 1) {
                    walls.add(row + "," + col + "," + row + "," + (col - 1));
                }
                if (col <= 23) {
                    walls.add(row + "," + col + "," + row + "," + (col + 1));
                }
            } else {
                walls.remove(index);
            }
        }
        Main.mazeLabels[19][24].setTarget();
        Main.mazeLabels[19][24].repaint();
        Main.mazeLabels[0][0].setCurrent();
        Main.mazeLabels[0][0].repaint();
    }
}

class GetWay {
    private static boolean[][] visit;
    private static Stack stack;

    public static void getWay(){
        visit = new boolean[20][25];
        stack = new Stack();
        DFS();
        showRes();
        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < 25; j++) {
                Main.mazeLabels[i][j].repaint();
            }
        }
    }

    private static void DFS(){
        stack.push(Main.mazeLabels[0][0]);
        visit[0][0] = true;
        while (!stack.isEmpty()) {
            MazeLabel cur = stack.pop();
            int row = cur.row;
            int col = cur.col;
            if (row == 19 && col == 24) {
                stack.push(cur);
                break;
            }
            for (int d = 0; d < 4; d++) {
                if (d == 0) {
                    if (Main.mazeLabels[row][col].isUpAlready() && !visit[row - 1][col]) {
                        stack.push(cur);
                        stack.push(Main.mazeLabels[row - 1][col]);
                        visit[row][col] = true;
                        visit[row - 1][col] = true;
                    }
                } else if (d == 1) {
                    if (Main.mazeLabels[row][col].isDownAlready() && !visit[row + 1][col]) {
                        stack.push(cur);
                        stack.push(Main.mazeLabels[row + 1][col]);
                        visit[row][col] = true;
                        visit[row + 1][col] = true;
                    }
                } else if (d == 2) {
                    if (Main.mazeLabels[row][col].isLeftAlready() && !visit[row][col - 1]) {
                        stack.push(cur);
                        stack.push(Main.mazeLabels[row][col - 1]);
                        visit[row][col] = true;
                        visit[row][col - 1] = true;
                    }
                } else {
                    if (Main.mazeLabels[row][col].isRightAlready() && !visit[row][col + 1]) {
                        stack.push(cur);
                        stack.push(Main.mazeLabels[row][col + 1]);
                        visit[row][col] = true;
                        visit[row][col + 1] = true;
                    }
                }
            }
        }
    }

    private static void showRes() {
        ArrayList<MazeLabel> list = stack.getList();
        ArrayList<MazeLabel> toRemove = new ArrayList<>();
        for (int i = 0; i < list.size() - 2; i++) {
            if (list.get(i) == list.get(i + 2)) {
                toRemove.add(list.get(i + 1));
            }
        }
        for (int i = toRemove.size() - 1; i >= 0; i--) {
            int index = list.indexOf(toRemove.get(i));
            list.remove(index + 1);
            list.remove(index);
        }
        for (int i = 0; i < list.size() - 1; i++) {
            MazeLabel cur = list.get(i);
            MazeLabel next = list.get(i + 1);
            if (next.row - cur.row == 1) {
                cur.downWay = true;
                next.upWay = true;
            } else if (cur.row - next.row == 1) {
                cur.upWay = true;
                next.downWay = true;
            } else if (next.col - cur.col == 1) {
                cur.rightWay = true;
                next.leftWay = true;
            } else if (cur.col - next.col == 1) {
                cur.leftWay = true;
                next.rightWay = true;
            }
        }
    }
}

class Stack {
    private ArrayList<MazeLabel> list;

    public Stack() {
        list = new ArrayList<>();
    }

    public void push(MazeLabel element) {
        list.add(element);
    }

    public MazeLabel pop() {
        return list.remove(list.size() - 1);
    }

    public MazeLabel getTop() {
        return list.get(list.size() - 1);
    }

    public boolean isEmpty() {
        return list.isEmpty();
    }

    public ArrayList<MazeLabel> getList() {
        return list;
    }
}

import java.util.ArrayDeque;

public class TestMaze {
    static int rows = 20, cols = 25;

    public static void main(String[] args) throws Exception {
        // headless grid init (mirrors Main.initTable without the JFrame)
        Main.mazeLabels = new MazeLabel[rows][cols];
        for (int i = 0; i < rows; i++)
            for (int j = 0; j < cols; j++) {
                Main.mazeLabels[i][j] = new MazeLabel();
                Main.mazeLabels[i][j].row = i;
                Main.mazeLabels[i][j].col = j;
            }

        for (int trial = 0; trial < 5; trial++) {
            MazeTools.generateNewMaze();
            checkMaze("DFS");
            checkSolver("DFS");
            PrimGenerate.primGenerate();
            checkMaze("Prim");
            checkSolver("Prim");
        }
        System.out.println("ALL TESTS PASSED");
    }

    // open if the wall between a and its neighbor was carved
    static boolean open(int r, int c, int dr, int dc) {
        MazeLabel a = Main.mazeLabels[r][c];
        if (dr == -1) return a.isUpAlready();
        if (dr == 1) return a.isDownAlready();
        if (dc == -1) return a.isLeftAlready();
        return a.isRightAlready();
    }

    static void checkMaze(String algo) {
        MazeLabel[][] m = Main.mazeLabels;
        // every cell visited during generation
        for (int i = 0; i < rows; i++)
            for (int j = 0; j < cols; j++)
                if (!m[i][j].getAlready())
                    throw new AssertionError(algo + ": cell " + i + "," + j + " not visited");
        // border walls intact
        for (int j = 0; j < cols; j++) {
            if (m[0][j].isUpAlready() || m[rows - 1][j].isDownAlready())
                throw new AssertionError(algo + ": border row wall opened");
        }
        for (int i = 0; i < rows; i++) {
            if (m[i][0].isLeftAlready() || m[i][cols - 1].isRightAlready())
                throw new AssertionError(algo + ": border col wall opened");
        }
        // wall symmetry between neighbours
        for (int i = 0; i < rows; i++)
            for (int j = 0; j < cols; j++) {
                if (i + 1 < rows && m[i][j].isDownAlready() != m[i + 1][j].isUpAlready())
                    throw new AssertionError(algo + ": asymmetric vertical wall at " + i + "," + j);
                if (j + 1 < cols && m[i][j].isRightAlready() != m[i][j + 1].isLeftAlready())
                    throw new AssertionError(algo + ": asymmetric horizontal wall at " + i + "," + j);
            }
        // fully connected (BFS over open walls reaches all 500 cells)
        boolean[][] seen = new boolean[rows][cols];
        ArrayDeque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{0, 0});
        seen[0][0] = true;
        int reached = 0;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            reached++;
            for (int[] d : dirs) {
                int nr = cur[0] + d[0], nc = cur[1] + d[1];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || seen[nr][nc]) continue;
                if (open(cur[0], cur[1], d[0], d[1])) {
                    seen[nr][nc] = true;
                    q.add(new int[]{nr, nc});
                }
            }
        }
        if (reached != rows * cols)
            throw new AssertionError(algo + ": maze not fully connected, reached " + reached);
        System.out.println(algo + " generation OK (connected, symmetric, all visited)");
    }

    static void checkSolver(String algo) {
        GetWay.getWay();
        MazeLabel[][] m = Main.mazeLabels;
        // walk the drawn way from (0,0); it must reach (19,24) without branches
        boolean[][] seen = new boolean[rows][cols];
        int r = 0, c = 0;
        seen[0][0] = true;
        int steps = 0;
        while (!(r == rows - 1 && c == cols - 1)) {
            int nr = -1, nc = -1, count = 0;
            MazeLabel cur = m[r][c];
            if (cur.upWay && r > 0 && !seen[r - 1][c]) { nr = r - 1; nc = c; count++; }
            if (cur.downWay && r < rows - 1 && !seen[r + 1][c]) { nr = r + 1; nc = c; count++; }
            if (cur.leftWay && c > 0 && !seen[r][c - 1]) { nr = r; nc = c - 1; count++; }
            if (cur.rightWay && c < cols - 1 && !seen[r][c + 1]) { nr = r; nc = c + 1; count++; }
            if (count != 1)
                throw new AssertionError(algo + " solver: path dead-end/branch at " + r + "," + c + " count=" + count);
            r = nr; c = nc;
            seen[r][c] = true;
            if (++steps > rows * cols)
                throw new AssertionError(algo + " solver: path too long / loop");
        }
        System.out.println(algo + " solver OK (path (0,0)->(19,24), length " + (steps + 1) + " cells)");
    }
}
